def topological_sort(graph: dict[str, list[str]]) -> tuple[list[str], list[str] | None]:
    """
    Returns a topological order of dependency keys from the given graph.

    Parameters:
    graph (dict): A dictionary representing an undirected graph where each key is a node and its value is a list of nodes it depends on.

    Returns:
    tuple: A sorted list of nodes in topological order, or None if there's a cycle.
    """
