        stack.append(node)

    # Initialize variables
    sorted_nodes = []
    cycle_nodes = None

    for node in graph.keys():
        if node not in visited:
            try:
                dfs(node)
            except ValueError as e:
                cycle_nodes = list(reversed(stack))
                return (sorted_nodes, cycle_nodes)

    while stack:
        node = stack.pop()
        sorted_nodes.append(node)

    # Check for disconnected subgraphs
    for node in graph.keys():
        if node not in visited and node not in topological_order:
            raise ValueError("Disconnected subgraph detected")

    return tuple(sorted_nodes), cycle_nodes

